'use client';
import cl from "clsx/lite";
import { forwardRef } from "react";
import { jsx } from "react/jsx-runtime";
//#region src/components/input/input.tsx
/**
* Input renders a native `input` element.
*
* @example
* <Input />
*/
const Input = forwardRef(function Input({ type = "text", className, onChange, onClick, ...rest }, ref) {
	return /* @__PURE__ */ jsx("input", {
		className: cl(`ds-input`, className),
		ref,
		type,
		suppressHydrationWarning: true,
		onChange: (event) => rest.readOnly || onChange?.(event),
		onClick: (event) => {
			if (rest.readOnly) event.preventDefault();
			onClick?.(event);
		},
		...rest
	});
});
//#endregion
export { Input };
